class Checks:
    def __init__(self) -> None:
        self.passed = 0
        self.failed = 0

    def check(self, key: str, statement: str, condition) -> None:
        ok = bool(condition)
        short = statement if len(statement) <= 91 else statement[:88] + "..."
        print(f"[{'PASS' if ok else 'FAIL'}] {key}: {short}")
        self.passed += int(ok)
        self.failed += int(not ok)

    def finish(self) -> int:
        print(f"TOTAL: PASS={self.passed} FAIL={self.failed}")
        return self.failed


def git_output(*args: str) -> str:
    return subprocess.check_output(
        ("git",) + args,
        cwd=ROOT,
        text=True,
        timeout=AUDIT_TIMEOUT_SEC,
    ).strip()


def worktree_blob(path: str) -> str:
    return git_output("hash-object", path)


def commit_blob(commit: str, path: str) -> str:
    return git_output("rev-parse", f"{commit}:{path}")


def is_ancestor(ancestor: str, descendant: str) -> bool:
    return subprocess.run(
        ("git", "merge-base", "--is-ancestor", ancestor, descendant),
        cwd=ROOT,
        check=False,
        timeout=AUDIT_TIMEOUT_SEC,
    ).returncode == 0


def authority_certificate(mutation: str) -> dict[str, object]:
    expected_axiom = (
        "0" * 40 if mutation == "stale_axiom_authority" else CURRENT_AXIOM_BLOB
    )
    expected_parent = (
        "0" * 40 if mutation == "stale_parent_authority" else PARENT_NOTE_BLOB
    )
    ancestors = {
        f"ancestor_{number}": is_ancestor(commit, "HEAD")
        for number, commit in (
            (112, ANCESTOR_112),
            (111, ANCESTOR_111),
            (110, ANCESTOR_110),
            (109, ANCESTOR_109),
            (108, ANCESTOR_108),
            (107, ANCESTOR_107),
            (106, ANCESTOR_106),
            (105, ANCESTOR_105),
            (104, ANCESTOR_104),
            (103, ANCESTOR_103),
        )
    }
    return {
        "main": git_output("rev-parse", "origin/main"),
        "axiom": commit_blob("origin/main", AXIOM_PATH),
        "worktree_axiom": worktree_blob(AXIOM_PATH),
        "expected_axiom": expected_axiom,
        "registry": commit_blob("origin/main", REGISTRY_PATH),
        "worktree_registry": worktree_blob(REGISTRY_PATH),
        "parent": git_output("rev-parse", PARENT_REF),
        "parent_ancestor": is_ancestor(PARENT_COMMIT, "HEAD"),
        **ancestors,
        "parent_note": commit_blob(PARENT_COMMIT, PARENT_NOTE),
        "expected_parent": expected_parent,
        "parent_runner": commit_blob(PARENT_COMMIT, PARENT_RUNNER),
        "parent_cache": commit_blob(PARENT_COMMIT, PARENT_CACHE),
    }


def canonical(value: sp.Expr) -> sp.Expr:
    return sp.cancel(sp.expand(value))


def matrix_equal(left: sp.Matrix, right: sp.Matrix) -> bool:
    return left.shape == right.shape and all(
        canonical(entry) == 0 for entry in left - right
    )


def literal_gaussian_matrix(
    rows: int,
    columns: int,
    denominator: int,
    entries: tuple[tuple[int, int, int], ...],
) -> sp.Matrix:
    if denominator <= 0 or len({index for index, _, _ in entries}) != len(entries):
        raise ValueError("invalid literal QQ(i) matrix")
    result = sp.zeros(rows, columns)
    for index, real, imaginary in entries:
        if not 0 <= index < rows * columns:
            raise ValueError("literal matrix index out of range")
        result[index // columns, index % columns] = (
            sp.Rational(real, denominator) + I * sp.Rational(imaginary, denominator)
        )
    return result


REAL_TENTHS = (
    (9, 9, 1, 6),
    (-3, -8, 1, 2),
    (-7, -2, 17, 0),
    (-2, 1, -11, 2),
)
IMAG_TENTHS = (
    (0, 0, 0, 16),
    (18, 8, -7, -3),
    (-31, -19, -40, -2),
    (-5, 1, 13, -3),
)


def positive_q(q00: sp.Expr = sp.Rational(9, 10)) -> sp.Matrix:
    result = sp.Matrix(
        4,
        4,
        lambda row, column: sp.Rational(REAL_TENTHS[row][column], 10)
        + I * sp.Rational(IMAG_TENTHS[row][column], 10),
    )
    result[0, 0] = q00
    return result


def lower_change(q: sp.Matrix) -> tuple[sp.Matrix, sp.Matrix]:
    change = sp.eye(8)
    inverse = sp.eye(8)
    change[4:8, 0:4] = q
    inverse[4:8, 0:4] = -q
    return change, inverse


def chart_block(q: sp.Matrix, u: sp.Matrix) -> sp.Matrix:
    change, inverse = lower_change(q)
    nilpotent = sp.zeros(8)
    nilpotent[0:4, 4:8] = u
    return change * (D8 + nilpotent) * inverse


def reality_mate(block: sp.Matrix) -> sp.Matrix:
    return J8 * block.conjugate() * J8


def assemble_from_momentum(blocks: tuple[sp.Matrix, ...]) -> sp.Matrix:
    if len(blocks) != 4 or any(block.shape != (8, 8) for block in blocks):
        raise ValueError("four literal 8-by-8 momentum blocks required")
    return sp.Matrix(
        32,
        32,
        lambda row, column: canonical(
            sum(
                I ** (momentum_index * ((column % 4) - (row % 4)))
                * blocks[momentum_index][row // 4, column // 4]
                for momentum_index in range(4)
            )
            / 4
        ),
    )


