@dataclass(frozen=True)
class WitnessData:
    shear: sp.Rational
    q: sp.Matrix
    u: sp.Matrix
    blocks: tuple[sp.Matrix, ...]
    operator: sp.Matrix


@dataclass(frozen=True)
class PositivityData:
    minors: tuple[sp.Expr, ...]
    minor_signs: tuple[int, ...]
    minor_inertia: tuple[int, int, int]
    coefficients: tuple[sp.Expr, ...]
    p_changes: int
    p_minus_changes: int
    charpoly_inertia: tuple[int, int, int]
    faddeev_residual_zero: bool
    pivots: tuple[sp.Expr, ...]
    pivot_signs: tuple[int, ...]
    pivot_inertia: tuple[int, int, int]
    ldl_reconstruction: bool


def pinned_witness(shear: sp.Rational) -> WitnessData:
    if shear == PRIMARY_SHEAR:
        a0 = literal_gaussian_matrix(
            8, 8, PRIMARY_A0_DENOMINATOR, PRIMARY_A0_SPARSE
        )
        u = literal_gaussian_matrix(4, 4, PRIMARY_U_DENOMINATOR, PRIMARY_U_SPARSE)
        a2 = literal_gaussian_matrix(
            8, 8, PRIMARY_A2_DENOMINATOR, PRIMARY_A2_SPARSE
        )
    elif shear == SECOND_SHEAR:
        a0 = literal_gaussian_matrix(
            8, 8, SECOND_A0_DENOMINATOR, SECOND_A0_SPARSE
        )
        u = literal_gaussian_matrix(4, 4, SECOND_U_DENOMINATOR, SECOND_U_SPARSE)
        a2 = literal_gaussian_matrix(
            8, 8, SECOND_A2_DENOMINATOR, SECOND_A2_SPARSE
        )
    else:
        raise ValueError("only the two displayed literal fixtures are pinned")
    q = positive_q()
    a1 = chart_block(q, u)
    a3 = reality_mate(a1)
    blocks = (a0, a1, a2, a3)
    return WitnessData(shear, q, u, blocks, assemble_from_momentum(blocks))


def crossing_paired_blocks() -> tuple[sp.Matrix, sp.Matrix, sp.Matrix]:
    q = positive_q(sp.Rational(4, 5))
    u = literal_gaussian_matrix(
        4, 4, CROSSING_U_DENOMINATOR, CROSSING_U_SPARSE
    )
    a1 = chart_block(q, u)
    return q, a1, reality_mate(a1)


def left_dressed_gram(operator: sp.Matrix, fixture) -> sp.Matrix:
    """Build K_A=(A P G)| on reflected histories, with A on the left."""
    full = operator * fixture.reflection * fixture.propagator
    reflected = tuple(fixture.reflected)
    return full.extract(reflected, reflected)


def block_gram(block: sp.Matrix, propagator_block: sp.Matrix) -> sp.Matrix:
    return (E4 * block * propagator_block * F4.T).applyfunc(canonical)


def qqi_rows(matrix: sp.Matrix):
    from sympy.polys.matrices import DomainMatrix

    domain_matrix = DomainMatrix.from_Matrix(matrix, fmt="dense").convert_to(sp.QQ_I)
    return domain_matrix.rep.to_list(), domain_matrix.domain


def qqi_conjugate(value):
    return sp.QQ_I(value.x, -value.y)


def qqi_sign(value) -> int:
    if value.y != 0:
        raise ArithmeticError("certified real QQ(i) value has nonzero imaginary part")
    return 1 if value.x > 0 else -1 if value.x < 0 else 0


def bareiss_leading_minors(matrix: sp.Matrix) -> tuple[sp.Expr, ...]:
    """Independent fraction-free route for every leading principal minor."""
    rows, domain = qqi_rows(matrix)
    size = len(rows)
    work = [row[:] for row in rows]
    previous = domain.one
    result = []
    for pivot_index in range(size - 1):
        pivot = work[pivot_index][pivot_index]
        if pivot == domain.zero:
            raise ArithmeticError("zero Bareiss pivot in leading-minor chain")
        result.append(domain.to_sympy(pivot))
        for row in range(pivot_index + 1, size):
            for column in range(pivot_index + 1, size):
                work[row][column] = (
                    work[row][column] * pivot
                    - work[row][pivot_index] * work[pivot_index][column]
                ) / previous
            work[row][pivot_index] = domain.zero
        previous = pivot
    result.append(domain.to_sympy(work[-1][-1]))
    return tuple(result)


def sign_changes(signs: tuple[int, ...]) -> int:
    nonzero = tuple(sign for sign in signs if sign)
    return sum(left != right for left, right in zip(nonzero, nonzero[1:]))


def inertia_from_leading_minors(
    minors: tuple[sp.Expr, ...],
) -> tuple[int, int, int]:
    previous = sp.Integer(1)
    pivot_signs = []
    for minor in minors:
        sign = qqi_sign(sp.QQ_I.from_sympy(canonical(minor / previous)))
        if sign == 0:
            return (-1, -1, -1)
        pivot_signs.append(sign)
        previous = minor
    positive = pivot_signs.count(1)
    negative = pivot_signs.count(-1)
    return positive, negative, len(minors) - positive - negative


def faddeev_leverrier(
    matrix: sp.Matrix,
) -> tuple[tuple[sp.Expr, ...], bool]:
    """Exact Faddeev--LeVerrier over QQ(i), independent of determinants."""
    from sympy.polys.matrices import DomainMatrix

    operator = DomainMatrix.from_Matrix(matrix, fmt="dense").convert_to(sp.QQ_I)
    operator = operator.to_dense()
    domain = operator.domain
    identity = DomainMatrix.eye(operator.shape, domain).to_dense()
    recurrence = identity
    coefficients = [domain.one]
    for index in range(1, matrix.rows + 1):
        product = operator.matmul(recurrence)
        trace = sum(
            (product[row, row].element for row in range(matrix.rows)),
            domain.zero,
        )
        coefficient = -trace / domain.convert(index)
        coefficients.append(coefficient)
        recurrence = product.to_dense().add(
            identity.scalarmul(coefficient).to_dense()
        )
    residual_zero = all(
        recurrence[row, column].element == domain.zero
        for row in range(matrix.rows)
        for column in range(matrix.cols)
    )
    return tuple(domain.to_sympy(value) for value in coefficients), residual_zero


def ldl_pivots(matrix: sp.Matrix) -> tuple[tuple[sp.Expr, ...], bool]:
    """Independent scalar LDL^H recursion, including an exact reconstruction."""
    rows, domain = qqi_rows(matrix)
    size = len(rows)
    lower = [[domain.zero for _ in range(size)] for _ in range(size)]
    pivots = []
    for column in range(size):
        pivot = rows[column][column] - sum(
            (
                lower[column][index]
                * pivots[index]
                * qqi_conjugate(lower[column][index])
                for index in range(column)
            ),
            domain.zero,
        )
        if pivot == domain.zero:
            raise ArithmeticError("zero LDL pivot")
        pivots.append(pivot)
        lower[column][column] = domain.one
        for row in range(column + 1, size):
            numerator = rows[row][column] - sum(
                (
                    lower[row][index]
                    * pivots[index]
                    * qqi_conjugate(lower[column][index])
                    for index in range(column)
                ),
                domain.zero,
            )
            lower[row][column] = numerator / pivot
    reconstruction = all(
        rows[row][column]
        == sum(
            (
                lower[row][index]
                * pivots[index]
                * qqi_conjugate(lower[column][index])
                for index in range(size)
            ),
            domain.zero,
        )
        for row in range(size)
        for column in range(size)
    )
    return tuple(domain.to_sympy(value) for value in pivots), reconstruction


def positivity_certificate(matrix: sp.Matrix) -> PositivityData:
    minors = bareiss_leading_minors(matrix)
    minor_signs = tuple(qqi_sign(sp.QQ_I.from_sympy(value)) for value in minors)
    minor_inertia = (matrix.rows, 0, 0) if all(sign > 0 for sign in minor_signs) else inertia_from_leading_minors(minors)

    coefficients, faddeev_residual_zero = faddeev_leverrier(matrix)
    coefficient_signs = tuple(
        qqi_sign(sp.QQ_I.from_sympy(value)) for value in coefficients
    )
    minus_signs = tuple(
        ((-1) ** (matrix.rows - index)) * sign
        for index, sign in enumerate(coefficient_signs)
    )
    p_changes = sign_changes(coefficient_signs)
    p_minus_changes = sign_changes(minus_signs)
    charpoly_inertia = (
        p_changes,
        p_minus_changes,
        matrix.rows - p_changes - p_minus_changes,
    )

    pivots, ldl_reconstruction = ldl_pivots(matrix)
    pivot_signs = tuple(qqi_sign(sp.QQ_I.from_sympy(value)) for value in pivots)
    pivot_inertia = (
        pivot_signs.count(1),
        pivot_signs.count(-1),
        pivot_signs.count(0),
    )
    return PositivityData(
        minors,
        minor_signs,
        minor_inertia,
        coefficients,
        p_changes,
        p_minus_changes,
        charpoly_inertia,
        faddeev_residual_zero,
        pivots,
        pivot_signs,
        pivot_inertia,
        ldl_reconstruction,
    )


def nonzero_entry_count(matrix: sp.Matrix) -> int:
    return sum(canonical(entry) != 0 for entry in matrix)


def occupied_slice_blocks(operator: sp.Matrix) -> int:
    return sum(
        any(
            canonical(operator[4 * left + row, 4 * right + column]) != 0
            for row in range(4)
            for column in range(4)
        )
        for left in range(8)
        for right in range(8)
    )


def short_fraction(value: sp.Expr, limit: int = 78) -> str:
    exact = str(canonical(value))
    if len(exact) <= limit:
        return exact
    numerator, denominator = sp.fraction(canonical(value))
    numerator_text = str(numerator)
    denominator_text = str(denominator)

    def clipped(text: str) -> str:
        return text if len(text) <= 28 else text[:13] + "..." + text[-12:]

    return f"{clipped(numerator_text)}/{clipped(denominator_text)}"


def exact_off_diagonal_entries(
    matrix: sp.Matrix,
) -> tuple[tuple[int, int, sp.Expr], tuple[int, int, sp.Expr]]:
    choices = sorted(
        (
            (len(str(canonical(matrix[row, column]))), row, column)
            for row in range(matrix.rows)
            for column in range(matrix.cols)
            if row != column and canonical(matrix[row, column]) != 0
        )
    )
    first = choices[0]
    second = next(
        item
        for item in choices[1:]
        if canonical(matrix[item[1], item[2]])
        != canonical(matrix[first[1], first[2]])
    )
    return (
        (first[1], first[2], canonical(matrix[first[1], first[2]])),
        (second[1], second[2], canonical(matrix[second[1], second[2]])),
    )


def same_chart_crossing(
    primary: WitnessData,
    fixture,
) -> tuple[tuple[int, int, int], tuple[int, int, int]]:
    propagators = tuple(
        momentum.momentum_block(fixture.propagator, index) for index in range(4)
    )
    _, _, lower_a3 = crossing_paired_blocks()
    lower_gram = block_gram(lower_a3, propagators[3])
    upper_gram = block_gram(primary.blocks[3], propagators[3])
    if not matrix_equal(lower_gram, lower_gram.H):
        return (-1, -1, -1), (-1, -1, -1)
    if not matrix_equal(upper_gram, upper_gram.H):
        return (-1, -1, -1), (-1, -1, -1)
    return (
        inertia_from_leading_minors(bareiss_leading_minors(lower_gram)),
        inertia_from_leading_minors(bareiss_leading_minors(upper_gram)),
    )


def structural_variety_certificate(
    primary: WitnessData,
    fixture,
) -> dict[str, object]:
    symbols = sp.symbols("n0:16")
    symbolic_n = sp.zeros(8)
    symbolic_n[0:4, 4:8] = sp.Matrix(4, 4, symbols)
    symbolic_operator = D8 + symbolic_n
    structural_residual = symbolic_operator * symbolic_operator - IDENTITY_8
    structural = (
        len(structural_residual) == 64
        and len(symbolic_operator.free_symbols) == 16
        and all(sp.expand(entry) == 0 for entry in structural_residual)
    )

    perturbed_u = primary.u.copy()
    perturbed_u[0, 0] += sp.Rational(1, 1000)
    perturbed_a1 = chart_block(primary.q, perturbed_u)
    perturbed_blocks = (
        primary.blocks[0],
        perturbed_a1,
        primary.blocks[2],
        reality_mate(perturbed_a1),
    )
    perturbed = assemble_from_momentum(perturbed_blocks)
    perturbed_gram = left_dressed_gram(perturbed, fixture)
    hermiticity_residual = perturbed_gram - perturbed_gram.H
    return {
        "structural": structural,
        "involution": matrix_equal(perturbed * perturbed, IDENTITY_32),
        "reality": matrix_equal(
            fixture.reflection * perturbed.conjugate() * fixture.reflection,
            perturbed,
        ),
        "broken_entries": nonzero_entry_count(hermiticity_residual),
    }


PENCIL_A = 1419397131814909
PENCIL_B = 634186515042025


def circle_mechanism_certificate(fixture) -> dict[str, object]:
    from sympy.polys.matrices import DomainMatrix

    circle, circle_blocks = prior.pinned_circulant(
        prior.PRIMARY_C_A1_DENOMINATOR,
        prior.PRIMARY_C_A1_SPARSE,
    )
    astar = base.global_candidate()
    k_circle = left_dressed_gram(circle, fixture)
    k_star = left_dressed_gram(astar, fixture)

    t, s = sp.symbols("t s", real=True)
    trace_circle = canonical(sp.trace(k_circle))
    trace_star = canonical(sp.trace(k_star))
    trace_identity = canonical(
        sp.trace(t * k_circle + s * k_star) - t * trace_circle
    ) == 0

    star_domain = DomainMatrix.from_Matrix(k_star, fmt="dense").convert_to(sp.QQ_I)
    circle_domain = DomainMatrix.from_Matrix(k_circle, fmt="dense").convert_to(sp.QQ_I)
    pencil = star_domain.to_dense().inv().matmul(circle_domain.to_dense()).to_Matrix()
    coefficients, faddeev_zero = faddeev_leverrier(pencil)
    r = sp.symbols("r")
    computed = sum(
        coefficient * r ** (16 - index)
        for index, coefficient in enumerate(coefficients)
    )
    pinned_factor = (
        r**4
        * (r**2 + 1) ** 4
        * (PENCIL_A * r**2 - PENCIL_B) ** 2
        / sp.Integer(PENCIL_A**2)
    )
    factor_verified = sp.Poly(computed - pinned_factor, r).is_zero

    propagators = tuple(
        momentum.momentum_block(fixture.propagator, index) for index in range(4)
    )
    endpoint_grams = tuple(
        block_gram(circle_blocks[index], propagators[index]) for index in range(4)
    )
    endpoint_parts = []
    endpoint_exact = all(
        matrix_equal(block, block.H) for block in endpoint_grams
    )
    for index, block in enumerate(endpoint_grams):
        if index in (0, 2):
            determinant_two = canonical(block[:2, :2].det(method="domain-ge"))
            part = (1, 1, 2) if block.rank() == 2 and determinant_two < 0 else (-1, -1, -1)
        else:
            part = inertia_from_leading_minors(bareiss_leading_minors(block))
        endpoint_parts.append(part)
    endpoint = tuple(sum(part[index] for part in endpoint_parts) for index in range(3))
    rank = endpoint[0] + endpoint[1]
    return {
        "circle": circle,
        "trace_circle": trace_circle,
        "trace_star": trace_star,
        "trace_identity": trace_identity,
        "factor_verified": factor_verified,
        "faddeev_zero": faddeev_zero,
        "endpoint_parts": tuple(endpoint_parts),
        "endpoint": endpoint,
        "rank": rank,
        "endpoint_exact": endpoint_exact,
        "involution": matrix_equal(circle * circle, IDENTITY_32),
        "reality": matrix_equal(
            fixture.reflection * circle.conjugate() * fixture.reflection,
            circle,
        ),
    }


def normalized_note() -> str:
    try:
        raw_note = NOTE_PATH.read_text(encoding="utf-8")
    except (FileNotFoundError, OSError, UnicodeError):
        return ""
    return " ".join(raw_note.lower().split())


